// 同一来源字段的不同条件生成独立记录，避免 DEV、LPDT 样例相互覆盖。
function capabilityPipelineSample(c){
 const base={},branches=new Map();
 for(const m of c.maps){
  if(!m.source.trim()||/(?:^|\.)(?:__proto__|constructor|prototype)(?:\.|$)/.test(m.source))continue;
  const path=m.source.replace(/^items\[\]\./,'').replace(/\[\]$/,''),[oid,pid]=m.target.split('.'),p=obj(oid)?.props.find(p=>p.id===pid),expected=String(m.conditionValue??'').trim();
  let value=p?.value??'示例值';if(/\[\]$/.test(m.source)||m.sourceType==='集合')value=Array.isArray(value)?value:[];
  if(expected){
   if((m.conditionOperator||'eq')==='eq')value=p?.type==='数字'&&Number.isFinite(Number(expected))?Number(expected):p?.type==='布尔'&&['true','false'].includes(expected)?expected==='true':expected;
   else if(String(value)===expected)value=typeof value==='number'?value+1:typeof value==='boolean'?!value:'其他值';
   if(!branches.has(path))branches.set(path,[]);if(!branches.get(path).some(v=>JSON.stringify(v)===JSON.stringify(value)))branches.get(path).push(value);
  }
  if(readPath(base,path)===undefined)assignPath(base,path,value);
 }
 for(const [path,values]of branches)assignPath(base,path,values[0]);
 if(c.object==='Context')return base;
 const rows=[base];for(const [path,values]of branches)for(const value of values.slice(1)){const row=structuredClone(base);assignPath(row,path,value);rows.push(row);}
 return {items:rows};
}
function callCapability(id,params={},failure='正常'){const c=ability(id),sys=c&&connector(c.connector);if(!c||!sys)return {ok:false,error:'查询或所属系统连接不存在'};if(!sys.enabled)return {ok:false,error:`系统连接 ${sys.name} 已停用，无法调用 ${c.name}`};if(failure==='超时')return {ok:false,error:`${sys.name} 模拟超时，未能取得数据，不能使用旧结果冒充通过`};for(const [key,label,required]of c.params){if(required==='是'&&!String(params[key]??'').trim())return {ok:false,error:`缺少必需参数：${label}（${key}）`}}let raw;
if(id==='pis.searchMaterials'){const word=String(params.keyword||'').trim().toLowerCase();raw={items:catalog.filter(m=>!word||(m.materialCode+m.materialName+m.modelCode).toLowerCase().includes(word)).map(m=>({MATERIAL_CODE:m.materialCode,MATERIAL_NAME:m.materialName,MODEL_CODE:m.modelCode}))};}
else if(id==='pis.getMaterial'){const m=catalog.find(m=>m.materialCode===params.materialCode);if(!m)return {ok:false,error:'PIS 未找到该整机物料，无法解析确认同一条记录'};raw={MATERIAL_CODE:m.materialCode,MATERIAL_NAME:m.materialName,MODEL_CODE:m.modelCode};}
else if(id==='irdms.projectMaterials'){const codes=params.projectCode==='PRJ-2026-A'?['MAT-20260081','MAT-20260082']:params.projectCode==='PRJ-2026-B'?['MAT-20260099']:[];raw={projectCode:params.projectCode,items:codes.map(materialCode=>({materialCode}))};}
else if(id==='plm.queryBom'){if(!catalog.some(m=>m.materialCode===params.materialCode))return {ok:false,error:'PLM 样例中没有此整机物料的 BOM'};if(!['B2','B3'].includes(params.bomVersion))return {ok:false,error:'当前样例中不存在此 BOM 版本'};raw={materialCode:params.materialCode,version:params.bomVersion,parts:[{componentCode:'PART-001',status:'已发布'},{componentCode:'PART-002',status:params.bomVersion==='B2'?'开发中':'已发布'},{componentCode:'PART-003',status:'已发布'}]};}
else if(id==='cert.queryApplicable'){if(!catalog.some(m=>m.materialCode===params.materialCode))return {ok:false,error:'认证样例中没有此物料记录'};const valid=params.materialCode!=='MAT-20260099'&&params.region==='欧洲'&&params.effectiveDate>='2026-01-01'&&params.effectiveDate<='2027-08-31';raw={materialCode:params.materialCode,region:params.region,effectiveDate:params.effectiveDate,certifications:valid?[{id:'CERT-EU-026',name:'CE 认证',region:'欧洲',validUntil:'2027-08-31',status:'有效'}]:[]};}
else if(id==='software.getPackage')raw={materialCode:params.softwareCode,language:'多语言',version:'V5.8.2'};
else raw=capabilityPipelineSample(c);
if(failure==='空结果')raw={items:[],certifications:[]};
return {raw,...normalizeCapabilityOutput(c,raw),capability:id,connector:sys.id,revision:c.revision,params:structuredClone(params),at:now()};}
function sceneValue(s,path,m){if(path==='ReleaseOrder.region')return s.context.region;if(path==='Material.materialCode')return m.materialCode;if(path==='Material.materialName')return m.materialName;if(path==='Material.modelCode')return m.modelCode;if(path.endsWith('.materialRef'))return `Material:${m.materialCode}`;if(path.endsWith('.projectCode'))return s.context.projectCode;if(path==='TrialItem.bomVersion')return s.context.bomVersion;if(path==='TrialItem.quantity')return 10;return getValue(path)}
function evaluateScene(s,materialCode='MAT-20260081',failure='正常'){const calls=[];const query=(id,params)=>{const r=callCapability(id,params,failure);calls.push(r);return r};const candidate=query(s.candidate,s.candidate==='pis.searchMaterials'?{keyword:''}:{projectCode:s.context.projectCode});if(!candidate.ok)return {ok:false,calls,error:candidate.error};const allowed=candidate.normalized.map(x=>x.properties.materialCode);const m=catalog.find(m=>m.materialCode===materialCode);if(!allowed.includes(materialCode))return {ok:false,calls,error:`${materialCode} 不在本场景可选范围中；当前项目 ${s.context.projectCode} 允许 ${allowed.join('、')||'无物料'}`,allowed};const profile=query(s.master,{materialCode});if(!profile.ok)return {ok:false,calls,error:profile.error};let bom,cert,software;const profileData=profile.normalized.find(x=>x.identity===`Material:${materialCode}`);if(!profileData)return {ok:false,calls,error:'画像返回的物料身份与当前业务行不一致'};const checks=[{name:'可选范围与物料身份',pass:true,detail:`${materialCode} → ${profile.normalized[0].identity}`}];if(s.bom){bom=query('plm.queryBom',{materialCode,bomVersion:s.context.bomVersion});if(!bom.ok)return {ok:false,calls,error:bom.error};const bomData=bom.normalized?.bom;if(typeof bomData?.version!=='string'||!Array.isArray(bomData.parts))return {ok:false,calls,error:'BOM 必需属性缺失或未匹配取值条件'};const pass=bomData.version===s.context.bomVersion&&(sceneKind(s)==='trial'?bomData.parts.length>0:bomData.parts.length>0&&bomData.parts.every(p=>p.status==='已发布'));checks.push({name:sceneKind(s)==='trial'?'试制 BOM 版本存在':'发布 BOM 受控零部件状态',pass,detail:`${s.context.bomVersion}：${bomData.parts.map(p=>`${p.componentCode} ${p.status}`).join('；')}`});}if(s.cert){cert=query('cert.queryApplicable',{materialCode,region:s.context.region,effectiveDate:s.context.effectiveDate});if(!cert.ok)return {ok:false,calls,error:cert.error};if(!Array.isArray(cert.normalized?.certifications))return {ok:false,calls,error:'认证属性缺失或未匹配取值条件'};checks.push({name:'本次区域与日期的认证要求',pass:cert.normalized.certifications.length>0,detail:`${s.context.region} / ${s.context.effectiveDate} → ${cert.normalized.certifications.length?'存在适用有效认证':'没有适用有效认证'}`});}if(sceneKind(s)==='release'){software=query('software.getPackage',{softwareCode:'SW-20260032'});if(!software.ok)return {ok:false,calls,error:software.error};}if(sceneKind(s)==='trial')checks.push({name:'试制数量有效',pass:true,detail:'样例数量 10 > 0'});if(sceneKind(s)==='range')checks.push({name:'范围内物料不重复',pass:true,detail:'本次样例只添加一条物料，不存在重复行'});checks.forEach((c,i)=>{c.name=s.rules[i]||c.name;c.level=s.ruleLevels?.[i]||'阻断'});const payload={};for(const bs of Object.values(s.bindings))for(const b of bs){const [section,key]=b.target.split('.');const val=b.ontology.startsWith('Software.')&&software?software.normalized[0].properties[b.ontology.split('.')[1]]:sceneValue(s,b.ontology,profileData.properties);if(section.endsWith('[]')){const n=section.slice(0,-2);payload[n]??=[{}];payload[n][0][key]=val}else{payload[section]??={};payload[section][key]=val}}return {ok:true,calls,allowed,identity:profile.normalized[0].identity,profile:profile.normalized[0].properties,context:structuredClone(s.context),checks,passed:checks.every(c=>c.pass||c.level==='警告'),payload,sceneRevision:s.revision};}
function abilityEditor(){
 const d=state.drawer,c=d.draft,o=obj(c.object),isContext=c.object==='Context',isDatabase=c.method==='数据库查询';
 return frame(d.isNew?'新增取数能力':`配置查询 · ${esc(c.name)}`,'先选从哪个系统查询，再设置查询结果对应的本体对象属性。',`
 <div class="form-grid">${field('这项查询叫什么 *','name',c.name,'text',[],'例如：按物料编码查询名称和型号')}${field('查询英文代号 *','id',c.id,'text',[],'供其他配置引用，例如 pis.getMaterial')}${field('从哪个系统查询','connector',c.connector,'select',systemConnectors.map(s=>[s.id,s.name]))}${field('查询结果属于哪个本体对象','object',c.object,'select',[...objects.map(o=>[o.id,o.name]),['Context','只用于本次业务校验的数据']])}${field('怎样查询','method',c.method,'select',[['GET','读取接口（GET）'],['POST 查询','带条件查询接口（POST）'],['数据库查询','读取数据库表']])}${field(isDatabase?'从哪张表查询 *':'调用哪个接口 *','resource',c.resource,'text',[],isDatabase?'填写来源表名，例如 PIS_MATERIAL；原型使用样例数据':'填写接口地址，例如 /materials/{materialCode}；原型使用样例数据',true)}${field('查询时需要哪些条件','paramText',c.paramText,'text',[],'填条件的英文名称，用逗号分开。例如 materialCode 表示物料编码，bomVersion 表示 BOM 版本；具体值在使用时提供。',true)}</div>
 <hr class="divider"><div class="between"><h3>${isContext?'设置本次校验要用的数据':`把查询结果对应到“${esc(o?.name||'本体对象')}”的属性`}</h3>${btn('添加字段对应','cap-add-map','sm','plus')}</div>
 <p class="tiny muted section-gap">${isDatabase?'左边填数据库查询结果中的列名，右边选择它表示的本体对象属性。':'左边填接口返回的字段名；如果有多层结构，写完整位置，例如 data.material.code。右边选择它表示的本体对象属性。'}</p>
 ${d.targetChanged?`<div class="section-gap">${inf('本体对象已切换，请重新选择每个字段对应的属性。来源字段已保留。','amber')}</div>`:''}
 <div class="table-wrap section-gap"><table class="map-table capability-mapping-table"><thead><tr><th>从查询结果中取哪个字段</th><th>取值条件（选填）</th><th>${isContext?'保存为本次业务的哪个字段':'对应哪个本体对象属性'}</th><th>操作</th></tr></thead><tbody>${c.maps.map((m,i)=>`<tr><td><input aria-label="查询结果字段 ${i+1}" placeholder="${isDatabase?'例如 category':'例如 category 或 data.material.code'}" data-cap-map="${i}" data-key="source" value="${esc(m.source)}"></td><td><div class="capability-value-condition"><select aria-label="取值条件运算 ${i+1}" data-cap-map="${i}" data-key="conditionOperator">${options([['eq','等于'],['neq','不等于']],m.conditionOperator||'eq')}</select><input aria-label="取值条件比较值 ${i+1}" placeholder="留空不筛选" data-cap-map="${i}" data-key="conditionValue" value="${esc(m.conditionValue??'')}"><button class="link" data-action="cap-clear-condition" data-index="${i}" aria-label="清空取值条件 ${i+1}" title="清空取值条件">清空</button></div></td><td>${isContext?`<input aria-label="本次业务字段 ${i+1}" placeholder="例如 Context.bom.parts" data-cap-map="${i}" data-key="target" value="${esc(m.target)}">`:`<select aria-label="对应的本体对象属性 ${i+1}" data-cap-map="${i}" data-key="target">${options([['','请选择本体对象属性'],...(o?.props||[]).map(p=>[`${o.id}.${p.id}`,`${p.name}${p.key?'（唯一编号，必须选）':''}`])],m.target)}</select>`}</td><td><button class="link" data-action="cap-remove-map" data-index="${i}">移除</button></td></tr>`).join('')}</tbody></table></div>
 <p class="tiny muted section-gap">条件直接作用于来源字段，比较值留空不筛选。例如 category 等于 DEV → 开发代表。按文本匹配，区分大小写；无匹配不填入，多值冲突会提示错误；集合字段暂不支持取值条件。</p>
 <div class="section-gap">${inf(isContext?'例如：把返回的 parts[] 保存为 Context.bom.parts，供本次 BOM 校验使用。':`请至少对应“${esc(o?.props.find(p=>p.key)?.name||'唯一编号')}”，用它区分每条${esc(o?.name||'业务')}记录。`)}</div>
 <details class="section-gap plain-details"><summary>查看字段代码（供开发对接）</summary><div class="table-wrap section-gap"><table><thead><tr><th>查询结果里的字段</th><th>本体对象属性代码</th></tr></thead><tbody>${c.maps.map(m=>`<tr><td><code>${esc(m.source||'待填写')}</code></td><td><code>${esc(m.target||'待选择')}</code></td></tr>`).join('')}</tbody></table></div></details>`,btn('保存查询配置','save-capability','primary','check'),true);
}
function connectorEditor(){const d=state.drawer,c=d.draft;return frame(d.isNew?'新增系统连接':`编辑系统连接 · ${esc(c.name)}`,'一次维护系统访问配置，多个取数能力与业务场景复用。',`<div class="form-grid">${field('系统名称 *','name',c.name)}${field('系统连接英文代号 *','id',c.id)}${field('连接类型','kind',c.kind,'select',['数据库','REST API','MCP'])}${field('负责人','owner',c.owner)}${field('地址 / 数据库服务 *','endpoint',c.endpoint,'text',[],'使用 .invalid 或示例数据库地址，不访问实际系统',true)}${field('登录凭据名称','auth',c.auth,'text',[],'仅引用名称，不在原型中填写真实密钥',true)}${field('超时（毫秒）','timeout',c.timeout,'number')}${field('重试次数','retry',c.retry,'number')}${field('是否启用','active',c.enabled?'启用':'停用','select',['启用','停用'])}${field('系统用途','desc',c.desc,'textarea',[],null,true)}</div><div class="section-gap">${inf('停用系统连接后，依赖它的查询测试和场景调用会失败；不静默切换到其他数据来源。','amber')}</div>`,btn('保存系统连接','save-connector','primary','check'));}
