configErrors=function(){const errors=[];for(const o of objects){if(o.props.filter(p=>p.key).length!==1)errors.push(`${o.name} 需要且仅需一个唯一编号属性`);if(new Set(o.props.map(p=>p.id)).size!==o.props.length)errors.push(`${o.name} 有重复属性英文代号`)}for(const c of capabilities){if(!connector(c.connector))errors.push(`${c.name} 的系统连接不存在`);for(const m of c.maps){if(c.object!=='Context'){const [oid,pid]=m.target.split('.');if(!obj(oid)?.props.some(p=>p.id===pid))errors.push(`${c.name} 引用的本体对象属性不存在：${m.target}`)}}}for(const s of Object.values(appScenes)){if(!(s.workflow?.type==='qa'&&s.workflow.application?.qaScope==='platform')&&(!ability(s.candidate)||!ability(s.master)))errors.push(`${s.name} 引用的取数能力不存在`);for(const bs of Object.values(s.bindings)){if(new Set(bs.map(b=>b.target)).size!==bs.length)errors.push(`${s.name} 存在重复字段绑定`);for(const b of bs){const [oid,pid]=b.ontology.split('.');if(!obj(oid)?.props.some(p=>p.id===pid))errors.push(`${s.name} 引用的本体对象属性不存在`)}}}return errors};
function studioReleasePage(){return header('配置发布','关联检查本体对象、取数能力与各应用场景的独立配置。',btn('检查配置','check-release','','shield')+btn(state.released?'已发布模拟版本':'发布配置包','publish','primary','upload',state.released?'disabled':''),'配置版本')+`<div class="two-cols"><section class="panel"><div class="panel-head"><h3>通用配置</h3></div><div class="panel-body">${[[`${objects.length} 个本体对象`,'业务含义、属性与唯一编号'],[`${systemConnectors.length} 个系统连接`,'访问方式、认证引用及启停'],[`${capabilities.length} 项可供多个场景使用的查询`,'查询条件、返回数据和对应的本体对象属性']].map(([t,d])=>`<div class="release-line"><div class="release-check">${icon('check')}</div><div><h4>${t}</h4><p>${d}</p></div></div>`).join('')}${inf('对象属性无需先指定唯一来源；实际来源由查询和场景的使用方式共同确定。')}</div></section><section class="panel"><div class="panel-head"><h3>场景配置分别维护</h3></div><div class="panel-body">${Object.values(appScenes).map(s=>`<div class="release-line"><div class="fill"><h4>${s.name} ${pill(s.version)}</h4><p>场景修订 ${s.revision} · ${Object.values(s.bindings).flat().length} 项绑定 · ${s.rules.length} 项规则</p></div><button class="link" data-action="open-scene" data-id="${s.id}">查看</button></div>`).join('')}<div class="section-gap">${inf(state.released?`模拟配置包 release-app-v${state.version}.0 已发布。`:'配置检查通过后可发布模拟版本；不会向真实业务系统提交任何单据。',state.released?'green':'')}</div></div></section></div>`}
checkReleaseDrawer=function(){const errors=configErrors();return frame('检查对象、取数能力和应用场景','本体对象、取数能力、场景绑定与引用一致性。',`${inf(errors.length?errors.join('；'):`检查通过：本体对象身份、查询结果及 ${Object.keys(appScenes).length} 个场景引用有效。`,errors.length?'red':'green')}<div class="section-gap">${jsonView({ontologyObjects:objects.length,connectors:systemConnectors.length,capabilities:capabilities.length,scenes:Object.values(appScenes).map(s=>({scene:s.name,revision:s.revision,candidate:s.candidate,master:s.master,bindings:Object.values(s.bindings).flat().length}))})}</div>`,errors.length?'':btn('发布模拟配置包','publish','primary','upload'),true)};
const originalResultFor=resultFor;
resultFor=function(i){const s=appScenes.release;if(i===1){if(state.timeout)return originalResultFor(i);const r=callCapability('plm.queryBom',{materialCode:'MAT-20260081',bomVersion:s.context.bomVersion});if(!r.ok)return {status:'未知',detail:r.error,proof:'PLM 查询失败',color:'amber'};const data=r.normalized?.bom;if(typeof data?.version!=='string'||!Array.isArray(data.parts))return {status:'未知',detail:'BOM 必需属性缺失或未匹配取值条件',proof:'整理后的 BOM 不完整',color:'amber'};const allReleased=data.version===s.context.bomVersion&&data.parts.length>0&&data.parts.every(x=>x.status==='已发布');return {status:allReleased?'通过':'阻断',detail:`本次 BOM ${s.context.bomVersion}：${allReleased?'全部受控零部件已发布':'存在尚未发布的受控零部件'}`,proof:`PLM · materialCode=MAT-20260081 · bomVersion=${s.context.bomVersion}`,color:allReleased?'green':'red'};}if(i===2){const r=callCapability('cert.queryApplicable',{materialCode:'MAT-20260081',region:s.context.region,effectiveDate:s.context.effectiveDate});if(!r.ok)return {status:'未知',detail:r.error,proof:'认证查询失败',color:'amber'};if(!Array.isArray(r.normalized?.certifications))return {status:'未知',detail:'认证属性缺失或未匹配取值条件',proof:'整理后的认证不完整',color:'amber'};const pass=!!r.normalized.certifications.length;return {status:pass?'通过':'阻断',detail:`${s.context.region} / ${s.context.effectiveDate}：${pass?'有适用有效认证':'无适用有效认证'}`,proof:`认证系统 · region=${s.context.region} · date=${s.context.effectiveDate}`,color:pass?'green':'red'};}return originalResultFor(i)};
