canSubmit=function(){const gate=evaluateScene(appScenes.release);return previousCanSubmit()&&gate.ok&&gate.passed};
const beforeGateDrawer=validateDrawer;
validateDrawer=function(){const gate=evaluateScene(appScenes.release);const reason=!gate.ok?gate.error:gate.checks.filter(c=>!c.pass&&c.level!=='警告').map(c=>c.name).join('、');return beforeGateDrawer().replace('<h3>提交前校验</h3>',`<h3>提交前校验</h3>${reason?`<span class="pill red">当前场景门禁：${esc(reason)}</span>`:''}`)};

// 模板保留初始配置，不依赖场景记录是否仍然存在。
const sceneTemplates=structuredClone(appScenes);

// Object selections for knowledge associations use the same drawer draft as text fields.
extraDrawers.knowledgeLink=knowledgeLinkDrawer;
document.addEventListener('change',e=>{const el=e.target,d=state.drawer;if(!el.dataset.knowledgeObject||d?.type!=='knowledgeLink')return;const id=el.dataset.knowledgeObject;d.draft.objects=d.draft.objects.filter(value=>value!==id);if(el.checked)d.draft.objects.push(id);d.dirty=true;d.error='';});
